 "content": "def transform(grid):
    """Copy the sole non-background compartment pattern into every compartment."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(x == v for row in g for x in row))
    # Full-length uniform lines are compartment dividers (including their crossings).
    div_rows = [r for r in range(h) if len(set(g[r])) == 1]
    div_cols = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1]
    row_edges = [-1] + div_rows + [h]
    col_edges = [-1] + div_cols + [w]
    row_spans = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1) if row_edges[i + 1] > row_edges[i] + 1]
    col_spans = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1) if col_edges[i + 1] > col_edges[i] + 1]
    panels = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            panel = [row[c0:c1] for row in g[r0:r1]]
            if any(v != bg for row in panel for v in row):
                panels.append((r0, r1, c0, c1, panel))
    if len(panels) != 1:
        return g
    _, _, _, _, source = panels[0]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if (r1 - r0, c1 - c0) != (len(source), len(source[0])):
                continue
            for dr in range(len(source)):
                for dc in range(len(source[0])):
                    g[r0 + dr][c0 + dc] = source[dr][dc]
    return g
